// Parse the outreach request and build Airtable filter
const body = $input.first().json.body || $input.first().json;
const creatorIds = body.creator_ids || [];
const niches = Array.isArray(body.niches) ? body.niches : (body.niches || '').split(',').map(s => s.trim()).filter(Boolean);
const budgetMax = body.budget_max || 10000;
const count = body.count || 10;
const brand = body.brand_name || '';
const niche = body.niche || niches.join(', ');
const budget = body.budget_per_video || budgetMax;
const template = body.message_template || '';

let filterFormula = '';
if (creatorIds.length > 0) {
  const orParts = creatorIds.map(id => `RECORD_ID()='${id}'`);
  filterFormula = `OR(${orParts.join(',')})`;
} else {
  // Auto-select: creators with email, matching niches, within budget
  const parts = ['email!=""'];
  if (niches.length > 0) {
    const nicheParts = niches.map(n => `FIND('${n}', ARRAYJOIN({niches}))`);
    parts.push(`OR(${nicheParts.join(',')})`);
  }
  if (budgetMax < 10000) {
    parts.push(`OR({rate_per_video}=0, {rate_per_video}<=${budgetMax})`);
  }
  filterFormula = parts.length > 1 ? `AND(${parts.join(',')})` : parts[0];
}

return [{ json: {
  filterFormula,
  brand, niche, budget, count, template,
  mode: creatorIds.length > 0 ? 'specific' : 'auto'
}}];

// Filter creators with valid emails and prepare the batch
const params = $('Parse Outreach Request').first().json;
const result = $input.first().json;
const records = (result.records || []).filter(r => {
  const f = r.fields;
  return f.email && f.email.includes('@');
});

// Limit to requested count
const selected = records.slice(0, params.count || 10);

if (selected.length === 0) {
  return [{ json: {
    creators: [],
    count: 0,
    hasCreators: false,
    error: 'No creators with email found matching criteria',
    params
  }}];
}

return [{ json: {
  creators: selected.map(r => ({
    id: r.id,
    name: r.fields.name || '',
    email: r.fields.email,
    instagram_handle: r.fields.instagram_handle || '',
    niches: Array.isArray(r.fields.niches) ? r.fields.niches : [],
    rate: r.fields.rate_per_video || 0,
    portfolio_url: r.fields.portfolio_url || '',
    location: r.fields.location || ''
  })),
  count: selected.length,
  hasCreators: true,
  params
}}];

// Parse Gemini email drafts and split into individual items
const response = $input.first().json;
const data = $('Filter & Prep Email Batch').first().json;

let emails = [];
try {
  let text = response.candidates?.[0]?.content?.parts?.[0]?.text || '[]';
  text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  emails = JSON.parse(text);
} catch (e) {
  // Fallback: generate generic emails
  emails = data.creators.map(c => ({
    email: c.email,
    name: c.name,
    subject: `Creator Collaboration Opportunity — ${data.params.niche || 'Brand Campaign'}`,
    body: `Hi ${c.name.split(' ')[0]},\n\nI came across your Instagram (${c.instagram_handle}) and love your content in the ${c.niches.join(', ')} space.\n\nWe're Smashed Agency, and we're looking for talented UGC creators for an upcoming brand campaign. Budget is INR ${data.params.budget || 'competitive'} per video.\n\nWould you be interested? Please reply with your portfolio and rate card.\n\nBest regards,\nTeam Smashed Agency`
  }));
}

// Enrich with creator IDs
const enriched = emails.map(e => {
  const creator = data.creators.find(c => c.email === e.email);
  return {
    ...e,
    creator_id: creator?.id || '',
    instagram_handle: creator?.instagram_handle || ''
  };
});

return enriched.map(e => ({ json: e }));

// Build RFC 2822 email and base64url encode for Gmail API
const email = $input.first().json;

const rawEmail = [
  'From: Smashed Agency <hello@smashedagency.com>',
  'To: ' + email.name + ' <' + email.email + '>',
  'Subject: ' + email.subject,
  'Content-Type: text/plain; charset=UTF-8',
  '',
  email.body
].join('\r\n');

const base64 = Buffer.from(rawEmail).toString('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

return [{ json: {
  raw: base64,
  creator_id: email.creator_id,
  email: email.email,
  name: email.name,
  subject: email.subject,
  body_preview: email.body.substring(0, 100)
}}];

// Aggregate all outreach results
const items = $input.all();
const results = items.map(i => {
  const j = i.json;
  // Gmail returns id+threadId on success; Airtable PATCH returns id+fields
  // After the chain: Gmail Send -> Update Creator, the output is from Airtable PATCH
  const fields = j.fields || {};
  const creatorName = fields.name || '';
  const creatorEmail = fields.email || '';
  const success = !!j.id;
  return {
    name: creatorName,
    email: creatorEmail,
    success,
    record_id: j.id || ''
  };
});

const sent = results.filter(r => r.success);
const failed = results.filter(r => !r.success);

return [{ json: {
  total: results.length,
  sent: sent.length,
  failed: failed.length,
  details: results,
  timestamp: new Date().toISOString()
}}];

// Filter creators who were contacted 3+ days ago and haven't been followed up
const result = $input.first().json;
const records = result.records || [];
const now = new Date();
const threeDaysMs = 3 * 24 * 60 * 60 * 1000;
const tenDaysMs = 10 * 24 * 60 * 60 * 1000;

const dueForFollowUp = [];

for (const r of records) {
  const notes = r.fields.notes || '';

  // Already followed up? Skip
  if (notes.includes('Follow-up sent')) continue;

  // Extract outreach date from notes
  const dateMatch = notes.match(/Outreach email sent on (\d{4}-\d{2}-\d{2})/);
  if (!dateMatch) continue;

  const sentDate = new Date(dateMatch[1]);
  const elapsed = now - sentDate;

  // Due: 3+ days but less than 10 days
  if (elapsed >= threeDaysMs && elapsed < tenDaysMs) {
    dueForFollowUp.push({
      id: r.id,
      name: r.fields.name || '',
      email: r.fields.email,
      instagram_handle: r.fields.instagram_handle || '',
      niches: Array.isArray(r.fields.niches) ? r.fields.niches : [],
      rate: r.fields.rate_per_video || 0,
      location: r.fields.location || '',
      sent_date: dateMatch[1],
      days_since: Math.floor(elapsed / (24 * 60 * 60 * 1000))
    });
  }
}

if (dueForFollowUp.length === 0) {
  return [{ json: { creators: [], count: 0, hasCreators: false } }];
}

return [{ json: { creators: dueForFollowUp, count: dueForFollowUp.length, hasCreators: true } }];

// Parse Gemini follow-up drafts and split into items
const response = $input.first().json;
const data = $('Filter Due Follow-ups').first().json;

let emails = [];
try {
  let text = response.candidates?.[0]?.content?.parts?.[0]?.text || '[]';
  text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  emails = JSON.parse(text);
} catch (e) {
  // Fallback: generic follow-up
  emails = data.creators.map(c => ({
    email: c.email,
    name: c.name,
    subject: `Following up — Creator Collaboration with Smashed Agency`,
    body: `Hi ${c.name.split(' ')[0]},\n\nJust following up on my email from ${c.days_since} days ago about a UGC creator collaboration opportunity with Smashed Agency.\n\nWe'd love to work with you! If you're interested, please reply with your portfolio and rate card.\n\nBest,\nTeam Smashed Agency`
  }));
}

const enriched = emails.map(e => {
  const creator = data.creators.find(c => c.email === e.email);
  return { ...e, creator_id: creator?.id || '', instagram_handle: creator?.instagram_handle || '' };
});

return enriched.map(e => ({ json: e }));

// Build RFC 2822 follow-up email and base64url encode
const email = $input.first().json;

const rawEmail = [
  'From: Smashed Agency <hello@smashedagency.com>',
  'To: ' + email.name + ' <' + email.email + '>',
  'Subject: ' + email.subject,
  'Content-Type: text/plain; charset=UTF-8',
  '',
  email.body
].join('\r\n');

const base64 = Buffer.from(rawEmail).toString('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

return [{ json: {
  raw: base64,
  creator_id: email.creator_id,
  email: email.email,
  name: email.name,
  subject: email.subject
}}];

// Aggregate follow-up results
const items = $input.all();
const count = items.length;
const names = items.map(i => (i.json.fields || {}).name || 'unknown').join(', ');
return [{ json: { follow_up_count: count, names, timestamp: new Date().toISOString() } }];

// Parse incoming creator reply
const body = $input.first().json.body || $input.first().json;
const creator_id = body.creator_id || '';
const reply_text = body.reply_text || '';
const portfolio_url = body.portfolio_url || '';
const email = body.email || '';

if (!creator_id && !email) {
  return [{ json: { error: 'creator_id or email required', success: false } }];
}

return [{ json: { creator_id, reply_text, portfolio_url, email, has_portfolio: !!portfolio_url } }];

// Build Airtable update payload for the reply
const data = $input.first().json;
const fields = {
  status: 'Active',
  notes: 'Replied on ' + new Date().toISOString().split('T')[0] + ' | ' + (data.reply_text || '').substring(0, 200)
};

if (data.portfolio_url) {
  fields.portfolio_url = data.portfolio_url;
  fields.status = 'Active'; // Will be upgraded to qualified if portfolio checks out
}

return [{ json: {
  creator_id: data.creator_id,
  update_body: { fields },
  reply_text: data.reply_text,
  portfolio_url: data.portfolio_url,
  has_portfolio: data.has_portfolio
}}];
